import validatorForm from './components/checkRulesManageComponent/validatorForm'
import { validatorSearch, validatorDel } from "@/api/system/checkRulesManage";

export default {
  components: {
    validatorForm
  },
  data() {
    return{
      tableData: [],
      tableHeight: undefined,
      tableLoading: false,
      // 弹窗
      showForm: false,
      showType: '',
      itemId: '',
    }
  },
  mounted() {
    this.setPageContentHeight()
    this.setTableHeight()
    this.getList()
  },
  methods: {
    // 设置表格高度
    setTableHeight() {
      let bodyBox = document.getElementsByClassName('page_body')
      this.tableHeight = bodyBox[0].offsetHeight + 'px'
    },
    getList() {
      this.tableLoading = true
      validatorSearch().then(res => {
        this.tableData = res.Return.tbodyList
        this.tableLoading = false
      }).catch(() => {
        this.tableLoading = false
      })
    },
    // 删除
    delItem(row) {
      this.$confirm('确定删除该全局属性?', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        validatorDel({id: row.id}).then(res => {
          this.$message({
            type: 'success',
            message: '删除成功！'
          });
          this.getList()
        })
      })
    },
    // 编辑
    editItem(row) {
      this.showType = '修改'
      this.itemId = row.id
      this.showForm = true
    },
    saveValidator() {
      this.showForm = false
      this.getList()
    }
  }
}
